    'energy.fx.night': 'P_nuit = s × P_moy = {s} × {avg} = {pn}\nE_nuit = P_nuit × t_nuit = {pn} × {tn} = {v}',
    'energy.fx.storage': 'η_d = √η_ar = √{rt} = {etad}\nC = E_nuit / (η_d × DoD) × (1 + m) = {en} / ({etad} × {dod}) × (1 + {m}) = {v}\nM = C / e_m = {v} / {se} = {mass}',
    'energy.fx.storageBuffer': 'η_d = √η_ar = √{rt} = {etad}\nLe tampon minimal dépasse l’énergie de nuit : E_tampon = P_moy × t_tampon = {avg} × {tb} = {buf}  (E_nuit = {en})\nC = E_tampon / (η_d × DoD) × (1 + m) = {buf} / ({etad} × {dod}) × (1 + {m}) = {v}\nM = C / e_m = {v} / {se} = {mass}',
    'energy.fx.recharge': 'P_rech = P_crête × f_dég × η_dist − P_moy = {kwp} × {dg} × {pm} − {avg} = {v}',
    'energy.fx.rechargeHours': 'Plein de la plus longue nuit, en plein Soleil : E_nuit / (η_ar × P_rech) = {en} / ({rt} × {v}) = {hours}',
    'energy.fx.solar': 'P_crête = plus petit champ solaire avec lequel la période rejouée heure par heure ne laisse rien non servi\n        (dichotomie ; plafond {cap}, soit {factor} × P_moy) = {v}\nA = P_crête / (S × η_cell) = {v} / ({S} × {cell}) = {area}\nM = A × μ = {area} × {mu} = {mass}',
    'energy.fx.archSolar': 'M = M_panneaux + M_stockage = {a} + {b} = {v}',
    'energy.fx.archFission': 'N = ⌈P_pointe / P_u⌉ + N_secours = ⌈{peak} / {pu}⌉ + {spare} = {n}\nP = N × P_u = {p}\nM = N × M_u = {n} × {mu} = {v}',
    'energy.fx.archHybrid': 'N = ⌈P_nuit / P_u⌉ = ⌈{pn} / {pu}⌉ = {n}\nSolaire = plus petit champ qui passe le rejeu avec ces réacteurs et le tampon = {sol}\nTampon : C_t = P_moy × t_tampon / (η_d × DoD) × (1 + m), avec t_tampon = {tb} : {buf}\nM = M_réacteurs + M_panneaux + M_tampon = {mf} + {ms} + {mb} = {v}',

