// Typographie française : espace insécable avant ; : ? ! % » et après «, pour qu'aucun de ces signes ne commence une ligne.
const NBSP = '\u00a0';
for (const key of Object.keys(dict.fr)) dict.fr[key] = dict.fr[key].replace(/ ([;:?!%»])/g, NBSP + '$1').replace(/« /g, '«' + NBSP);
register(dict);
